select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'catalog_work_descriptions:97' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146011 and t.language='nl')='{"text":"Na de dood van zijn vrouw leeft Mukesh teruggetrokken in Londen. Hij zou graag dichter bij zijn lezende kleindochter komen, maar weet weinig van haar boekenwereld. In de bibliotheek ontmoet hij Aleisha, een tiener die daar een zomerbaan heeft. Zij heeft een achtergelaten lijst met romans gevonden en is begonnen die te lezen. Wanneer ze de titels met Mukesh deelt, ontstaat tussen hen een band. Hun gesprekken over verhalen bieden een andere manier om met verlies en dagelijkse moeilijkheden om te gaan.","work_id":987146011,"evidence":[{"note":"Retain existing Work3244 The Reading List / Sara Nisha Adams and exact Dutch De troostbibliotheek 9789044365535 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-028.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p437921980"],"reference":"work:3244","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-028.json","sources":["https://openlibrary.org/works/OL24347979W","https://data.bibliotheken.nl/id/nbt/p437921980"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_