le-20261102-047","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987334002}'::jsonb as exact union all select 'catalog_work_descriptions:105' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146044 and t.language='nl')='{"text":"Prins Oak zit gevangen in het ijzige noorden en moet zich staande houden onder de macht van een nieuwe koningin. Ondertussen willen Cardan en Jude de erfgenaam van Elfhame terughalen. Oak staat daarmee tussen de belangen van zijn eigen rijk en zijn gevoelens voor Wren. Hij kan proberen haar vertrouwen terug te winnen of meewerken aan het beëindigen van haar heerschappij. Terwijl een nieuwe oorlog dichterbij komt, biedt zijn gebruikelijke handigheid met woorden en berekening niet vanzelf een veilige uitweg voor iedereen.","work_id":987146044,"evidence":[{"note":"Retain existing Work4926 The Prisoner''s Throne / Holly Black and exact Dutch De verloren troon 9789022598603 Hardcover. KB original-title/volume and existing source-edition parent compared; original content review content-review-028.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p440367719"],"reference":"work:4926","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-028.json","sources":["https://openlibrary.org/works/OL37617228W","https://data.bibliotheken.nl/id/nbt/p440367719"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789022598603","status":"no_veri